import { permit } from './limit.mjs';
const cases = [
  [-1, false, 'below lower boundary'],
  [0, true, 'lower inclusive endpoint'],
  [3, true, 'upper inclusive endpoint'],
  [4, false, 'above upper boundary'],
  ['3', false, 'numeric string malformed/non-Count'],
  [null, false, 'null malformed/non-Count'],
  [NaN, false, 'NaN malformed/non-Count'],
  [1.5, false, 'fraction malformed/non-Count'],
];
for (const [input, expected, label] of cases) {
  const actual = permit(input);
  console.log(`${label}: permit(${Object.is(input, NaN) ? 'NaN' : JSON.stringify(input)}) => ${actual}; expected ${expected}`);
  if (actual !== expected) process.exitCode = 1;
}
EOF
